public static final void main(String[] args) {
    final int N = getNextInt();
    final int M = getNextInt();
    final int[] A = getIntArray(N);
    final int[][] UV = get2dIntArray(M, 2, i -> i - 1);

    final List<List<Integer>> increasingEdgeList = Stream.generate(ArrayList<Integer>::new).limit(N).collect(Collectors.toCollection(ArrayList::new));
    for(int edge = 0; edge < M; edge++) {
        if(A[UV[edge][0]] < A[UV[edge][1]]) {
            increasingEdgeList.get(UV[edge][0]).add(UV[edge][1]);
        } else if(A[UV[edge][0]] > A[UV[edge][1]]) {
            increasingEdgeList.get(UV[edge][1]).add(UV[edge][0]);
        }
    }

    final PriorityQueue<int[]> pq = new PriorityQueue<>((e1, e2) -> e2[2] - e1[2]);
    final boolean[] passed = new boolean[N];
    pq.add(new int[] {0, 0, 1, A[0]});
    int maxScore = 0;

    while(!pq.isEmpty()) {
        final int[] pqGet = pq.poll();
        final int vertex = pqGet[1];
        final int distinctCount = pqGet[2];
        final int lastValue = pqGet[3];

        if(vertex == N - 1) {
            maxScore = Math.max(maxScore, distinctCount);
            continue;
        }

        if(passed[vertex]) {
            continue;
        }

        passed[vertex] = true;

        for(int next: increasingEdgeList.get(vertex)) {
            if(!passed[next] && A[next] >= lastValue) {
                pq.add(new int[] {A[next], next, distinctCount + (A[next] > lastValue ? 1 : 0), A[next]});
            }
        }
    }

    println(maxScore);
    flush();
}
